                    <p>Correct answers: ${data.correct.join(', ')}</p>
                </div>
            `;
        } else {
            feedbackHtml += `
                <div class="feedback-item incorrect">
                    <strong>Question ${qId.slice(1)}: Incorrect</strong>
                    <p>You selected: ${userAnswers.join(', ') || 'None'}</p>
                    <p>Correct answers: ${data.correct.join(', ')}</p>
                </div>
            `;
        }
    }

    scoreSummary.textContent = `You scored ${score} out of 3!`;
    detailedFeedback.innerHTML = feedbackHtml;

    form.hidden = true;
