    <script>
        const quizData = {
            q1: {
                correct: ['C', 'Rust', 'Assembly'],
                question: 'Which of these are considered "low-level" or "systems" languages?'
            },
            q2: {
                correct: ['JavaScript', 'TypeScript', 'Dart'],
                question: 'Which of these languages are commonly used for frontend web development?'
            },
            q3: {
                correct: ['Java', 'C#', 'Python'],
                question: 'Which of these are object-oriented programming (OOP) languages?'
            }
        };

        const form = document.getElementById('quiz-form');
        const resultsSection = document.getElementById('results');
        const scoreSummary = document.getElementById('score-summary');
        const detailedFeedback = document.getElementById('detailed-feedback');
        const retryBtn = document.getElementById('retry-btn');

        form.addEventListener('submit', (e) => {
            e.preventDefault();

            const formData = new FormData(form);
            const answers = {
                q1: formData.getAll('q1'),
                q2: formData.getAll('q2'),
                q3: formData.getAll('q3')
            };

            // Validation
            let hasErrors = false;
            let firstErrorField = null;

            for (const qId of Object.keys(quizData)) {
                const errorEl = document.getElementById(`${qId}-error`);
                if (answers[qId].length === 0) {
                    errorEl.hidden = false;
                    hasErrors = true;
                    if (!firstErrorField) {
                        firstErrorField = document.querySelector(`input[name="${qId}"]`);
                    }
                } else {
                    errorEl.hidden = true;
                }
            }

            if (hasErrors) {
                firstErrorField.focus();
                return;
            }

            // Calculation
            let score = 0;
            let feedbackHtml = '';

            for (const [qId, data] of Object.entries(quizData)) {
                const userAnswers = answers[qId];
                const isCorrect = 
                    userAnswers.length === data.correct.length && 
                    userAnswers.every(ans => data.correct.includes(ans));

                if (isCorrect) {
                    score++;
                    feedbackHtml += `
                        <div class="feedback-item correct">
                            <h3>Question ${qId.slice(1)}: Correct!</h3>
                            <p>${data.question}</p>
                            <p><strong>Correct answers:</strong> ${data.correct.join(', ')}</p>
                        </div>
                    `;
                } else {
                    feedbackHtml += `
                        <div class="feedback-item incorrect">
                            <h3>Question ${qId.slice(1)}: Incorrect</h3>
                            <p>${data.question}</p>
                            <p><strong>You selected:</strong> ${userAnswers.join(', ') || 'None'}</p>
                            <p><strong>Correct answers:</strong> ${data.correct.join(', ')}</p>
                        </div>
                    `;
                }
            }

            scoreSummary.textContent = `You scored ${score} out of 3!`;
            detailedFeedback.innerHTML = feedbackHtml;

            form.hidden = true;
            resultsSection.hidden = false;

            // Move focus to results heading
            const resultsHeading = document.getElementById('results-heading');
            resultsHeading.focus();
            resultsHeading.scrollIntoView({ behavior: 'smooth' });
        });

        retryBtn.addEventListener('click', () => {
            form.reset();
            // Hide all errors
            document.querySelectorAll('.error-message').forEach(el => el.hidden = true);
            form.hidden = false;
            resultsSection.hidden = true;
            window.scrollTo({ top: 0, behavior: 'smooth' });
            document.querySelector('h1').focus();
        });

        // Make h1 focusable for the retry action
        document.querySelector('h1').setAttribute('tabindex', '-1');
    </script>
</body>
